31: /**
32: * Computes the real part of the quotient.
33: *
34: * ## Notes
35: *
36: * -   See figure 10 of [Baudin (2012)][@baudin:2012].
37: *
38: * [@baudin:2012]: https://arxiv.org/abs/1210.4539
39: *
40: * @param re1       real component
41: * @param im1       imaginary component
42: * @param re2       real component
43: * @param im2       imaginary component
44: * @param r         partial result
45: * @param t         partial result
46: * @return          real part of the quotient
47: */
48: static double internalCompreal( const double re1, const double im1, const double re2, const double im2, const double r, const double t ) {
49: 	double br;
50: 	if ( r == 0.0 ) {
51: 		return ( re1 + (im2 * ( im1 / re2 )) ) * t;
52: 	}
53: 	br = im1 * r;
54: 	if ( br == 0.0 ) {
55: 		return ( re1 * t ) + ( ( im1 * t ) * r );
56: 	}
57: 	return ( re1 + br ) * t;
58: }
